package africa.growtogether.platform.eiam.mfa;
import africa.growtogether.platform.common.persistence.AuditedTenantEntity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="eiam_trusted_device",indexes={@Index(name="ix_trusted_device_user",columnList="tenant_id,user_id"),@Index(name="ix_trusted_device_token",columnList="token_hash",unique=true)})
public class TrustedDevice extends AuditedTenantEntity { @Column(name="user_id",nullable=false) private UUID userId; @Column(name="token_hash",nullable=false,length=64) private String tokenHash; @Column(name="device_name",nullable=false,length=150) private String deviceName; @Column(name="fingerprint_hash",nullable=false,length=64) private String fingerprintHash; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="last_used_at",nullable=false) private Instant lastUsedAt; @Column(name="revoked_at") private Instant revokedAt; protected TrustedDevice(){} public TrustedDevice(UUID userId,String tokenHash,String name,String fingerprintHash,Instant expiresAt,Instant now){this.userId=userId;this.tokenHash=tokenHash;this.deviceName=name;this.fingerprintHash=fingerprintHash;this.expiresAt=expiresAt;this.lastUsedAt=now;} public boolean trust(String fingerprint,Instant now){if(revokedAt!=null||!expiresAt.isAfter(now)||!fingerprintHash.equals(fingerprint))return false;lastUsedAt=now;return true;} public void revoke(Instant now){if(revokedAt==null)revokedAt=now;} public UUID getUserId(){return userId;} public String getDeviceName(){return deviceName;} public Instant getExpiresAt(){return expiresAt;} public Instant getLastUsedAt(){return lastUsedAt;} public Instant getRevokedAt(){return revokedAt;} }
